from __future__ import division, absolute_import, print_function,\
    unicode_literals

from future import standard_library
standard_library.install_aliases()


class TcpdumpError(Exception):
    """Exception  is raised if tshark error."""


class TcpdumpExecutionError(TcpdumpError):
    """Exception  is raised if shell command return code is not zero."""


class GettingPacketsNumberIsImpossible(TcpdumpError):
    """Exception is raised if is not possible to get packets number."""


class WaitingForPacketTimeout(TcpdumpError):
    """Exception is raised if waiting time expires."""


class ProcessIsAlreadyRunning(TcpdumpError):
    """Exception is raised if it is try of overwrite process."""


class StartProcessError(TcpdumpError):
    """Exception is raised if process is not able to start."""


class StopProcessError(TcpdumpError):
    """Exception is raised if process is not able to stop."""


class CapturingPacketsError(TcpdumpError):
    """Exception is raised if the number of packets captured is not equal to the given packet number. """
